import React, { useState, useEffect } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";
import "../styles/UserGig.css";

const UserGig = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [gig, setGig] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/gigs/${id}`);
        setGig(response.data);
      } catch (error) {
        console.error("Error fetching gig:", error);
        setError("Failed to load gig.");
      } finally {
        setLoading(false);
      }
    };

    fetchGig();
  }, [id]);

  if (loading) return <p className="user-gig-loading">Loading...</p>;
  if (error || !gig) return <p className="user-gig-error">No gig found.</p>;

  return (
    <div className="user-gig-wrapper">
      <div className="user-gig-card">
        <h2 className="user-gig-title">Gig Posting</h2>
        <p><strong>Title:</strong> {gig.title}</p>
        <p><strong>Gig Type:</strong> {gig.gigType}</p>
        <p><strong>Genre:</strong> {Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre}</p>
        <p><strong>City:</strong> {gig.city}</p>
        <p><strong>Description:</strong> {gig.description}</p>
        <p><strong>Date Posted:</strong> {new Date(gig.postingDate).toISOString().split("T")[0]}</p>
        <p><strong>Expires:</strong> {new Date(gig.expiryDate).toISOString().split("T")[0]}</p>
        <p><strong>Posted By:</strong> {gig.username}</p>

        <button className="view-profile-btn" onClick={() => navigate(-1)}>
          ← Back
        </button>
      </div>
    </div>
  );
};

export default UserGig;
